from pathlib import Path
P=Path(__file__).parent/'dist'
base=(P/'medical-safety.html').read_text()
header=base[base.index('<header class="site-header">'):base.index('</header>')+9]
footer=base[base.index('<footer>'):base.index('</footer>')+9]
head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#0b2740"><meta name="description" content="ArcHorizon is planned for open-source release, giving organizations room to adapt incident workflows, forms, maps, and deployment to their needs."><title>Open Source &amp; Adaptability | ArcHorizon</title><link rel="icon" type="image/png" href="archorizon-app-icon.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Exo+2:wght@600;700;800&family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="styles.css"><script src="theme.js" defer></script></head><body>'''
main='''<main class="source-page"><section class="source-hero"><div class="wrap"><div class="breadcrumb"><a href="index.html">Overview</a> / Open source</div><span class="eyebrow">Built to be adapted</span><h1>An incident platform should fit the organization using it.</h1><p>ArcHorizon is planned for open-source release. Access to the code gives agencies and volunteers a path to tailor workflows, inspect how information moves, and build integrations for their own operations.</p><div class="source-hero-links"><a href="#adapt">Explore the adaptation points ↓</a><a href="features.html">Browse the feature directory →</a></div></div></section><section class="section" id="adapt"><div class="wrap"><div class="section-head"><span class="eyebrow">Adaptability</span><h2>Keep the common picture. Change the parts that are local.</h2><p class="lead">The incident record connects people, tasks, geography, and reports. An open-source foundation makes it possible to adapt the surrounding workflows without giving up that shared structure.</p></div><div class="source-adapt-grid"><article><span>01 / WORKFLOWS</span><h3>Fit the incident</h3><p>Search and rescue, public safety incidents, and planned events use overlapping command principles but different field details. Organizations can shape views and task flows around the work they actually perform.</p><a href="operations.html">See Operations →</a></article><article><span>02 / FORMS</span><h3>Use the right documents</h3><p>Form profiles and field mappings can reflect the documents an agency uses, including different ICS profiles and local reporting needs.</p><a href="documentation.html">See Documentation →</a></article><article><span>03 / MAPS</span><h3>Bring local data</h3><p>Reference layers, public GIS services, and GeoJSON exchange let local geography and operational datasets contribute to the map.</p><a href="mapping.html">See Mapping →</a></article><article><span>04 / INTEGRATIONS</span><h3>Connect existing systems</h3><p>Open implementation details make it easier to build import, export, and service connections around existing agency tools.</p><a href="offline.html">See architecture →</a></article></div></div></section><section class="section alt"><div class="wrap source-architecture"><div><span class="eyebrow">Technical foundation</span><h2>Understand the pieces before changing them.</h2><p class="lead">The Windows-first desktop application uses Python and PySide6 Qt Widgets. It keeps local incident data available and can connect through a LAN server or cloud path. The companion app gives field personnel a focused view of the same work.</p><p>Geographic features can move between systems as GeoJSON. Form mappings and incident records provide other points where local needs can be expressed without rebuilding every screen.</p></div><div class="source-stack"><div><strong>Desktop</strong><span>Python · PySide6 Qt Widgets</span></div><div><strong>Data paths</strong><span>Local client · LAN server · cloud</span></div><div><strong>Field</strong><span>Companion mobile and tablet views</span></div><div><strong>Exchange</strong><span>GeoJSON and mapped form fields</span></div></div></div></section><section class="section"><div class="wrap source-proof"><div><span class="eyebrow">Practical flexibility</span><h2>Adapt a form or map layer without losing the incident thread.</h2><p class="lead">A local form can draw on the same subject, team, task, and activity records used elsewhere. A local map layer can sit alongside assignments and hazards. The value is in preserving the relationships while changing the pieces that vary by place or agency.</p></div><figure class="showcase-shot wide"><div class="showcase-placeholder"><span class="shot-kicker">DESKTOP SCREENSHOT SPACE</span><span class="shot-icon" aria-hidden="true">▣</span><strong>Forms registry or GIS layer manager</strong><span class="shot-note">Add your ArcHorizon capture here</span></div><figcaption>Suggested capture: a configurable form mapping or attached GIS dataset.</figcaption></figure></div></section><section class="section dark"><div class="wrap"><span class="eyebrow">Open-source release</span><h2>Code access supports scrutiny and contributions.</h2><p class="lead">Organizations can inspect how records connect, propose changes, and share improvements. The source repository and license will be linked here when the open-source release is published.</p><div class="related"><a href="features.html">Explore features →</a><a href="offline.html">Explore offline architecture →</a></div></div></section></main>'''
(P/'open-source.html').write_text(head+'<div id="top">'+header+main+footer+'</div></body></html>')
# Add a discoverable navigation and footer route without creating a dead repository link.
for f in P.glob('*.html'):
 s=f.read_text()
 if f.name!='open-source.html' and 'href="open-source.html"' not in s:
  s=s.replace('<a href="offline.html">Offline</a></nav>','<a href="offline.html">Offline</a><a href="open-source.html">Open source</a></nav>',1)
  s=s.replace('<li><a href="offline.html">Offline operation</a></li>','<li><a href="offline.html">Offline operation</a></li><li><a href="open-source.html">Open source</a></li>',1)
  f.write_text(s)
# The new page was built from a header/footer before those additions.
f=P/'open-source.html';s=f.read_text().replace('<a href="offline.html">Offline</a></nav>','<a href="offline.html">Offline</a><a href="open-source.html" aria-current="page">Open source</a></nav>',1).replace('<li><a href="offline.html">Offline operation</a></li>','<li><a href="offline.html">Offline operation</a></li><li><a href="open-source.html">Open source</a></li>',1);f.write_text(s)
# Home and feature directory make the open-source strategy visible.
f=P/'index.html';s=f.read_text();needle='<section class="section screenshot-section">';assert needle in s;s=s.replace(needle,'''<section class="section source-teaser"><div class="wrap split"><div><span class="eyebrow">Open source &amp; adaptable</span><h2>Make the platform fit your operation.</h2></div><div><p class="lead">ArcHorizon is planned for open-source release so organizations can adapt forms, map sources, workflows, and integrations to their own work.</p><a class="text-link" href="open-source.html">Explore the open-source approach →</a></div></div></section>'''+needle,1);f.write_text(s)
f=P/'features.html';s=f.read_text();needle='<section class="section screenshot-section">';assert needle in s;s=s.replace(needle,'''<section class="section source-teaser"><div class="wrap split"><div><span class="eyebrow">Open-source approach</span><h2>These sections can be adapted.</h2></div><div><p class="lead">The planned open-source release supports local forms, map data, workflows, and integrations while keeping an incident-wide record.</p><a class="text-link" href="open-source.html">How adaptability works →</a></div></div></section>'''+needle,1);f.write_text(s)
# SPE is placed between general ORM discussion and the ground release workflow.
f=P/'medical-safety.html';s=f.read_text();needle='<section class="section alt" id="release">';assert needle in s
spe='''<section class="section alt safety-spe"><div class="wrap"><div class="section-head"><span class="eyebrow">SPE risk assessment</span><h2>Look at severity, probability, and exposure.</h2><p class="lead">The SPE model gives Safety a structured way to assess a specific hazard before and after controls are applied. It makes the basis for a release discussion visible to the team and supervisor.</p></div><div class="spe-grid"><article><span>S</span><h3>Severity</h3><p>What is the credible consequence if this hazard results in harm?</p></article><article><span>P</span><h3>Probability</h3><p>How likely is the harmful event under the conditions of this assignment?</p></article><article><span>E</span><h3>Exposure</h3><p>How often, for how long, or how many people encounter the hazard?</p></article></div><div class="spe-workflow"><div><strong>Initial assessment</strong><span>Describe the hazard and evaluate the three factors.</span></div><div><strong>Controls</strong><span>Choose changes to the route, method, equipment, timing, or staffing.</span></div><div><strong>Residual review</strong><span>Reassess the remaining risk and record who reviewed the decision.</span></div></div><p class="spe-note">The assessment supports judgment and the appropriate release decision; the score does not make that decision on its own.</p></div></section>'''
s=s.replace(needle,spe+needle,1)
s=s.replace('The risk matrix gives staff a consistent way to consider likelihood and consequence. Record the factors, proposed controls, and review decision alongside the work being released.','The operational risk matrix gives staff a consistent way to review specific hazards. SPE adds exposure to the discussion of consequence and likelihood. Record the factors, controls, and review decision alongside the work being released.')
f.write_text(s)
css='''
/* Open-source page and explicit SPE model content. */
.source-hero{background:linear-gradient(112deg,#071c30,#113b55 70%,#325d74);color:#fff;border-bottom:4px solid var(--orange);padding:69px 0 78px}.source-hero .eyebrow{color:#ffad61}.source-hero .breadcrumb{color:#b9d0dc}.source-hero h1{max-width:950px}.source-hero p{max-width:850px;font-size:1.2rem;color:#d8e7ed}.source-hero-links{display:flex;flex-wrap:wrap;gap:18px 27px;margin-top:26px}.source-hero-links a{color:#ffb76f;font-weight:750;text-underline-offset:4px}.source-adapt-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:17px}.source-adapt-grid article{border:1px solid var(--line);border-top:4px solid var(--steel);padding:30px;background:#fff}.source-adapt-grid span{color:#a4550a;font-size:.77rem;font-weight:800;letter-spacing:.13em}.source-adapt-grid h3{margin:24px 0 12px}.source-adapt-grid p{color:var(--muted)}.source-adapt-grid a{color:#a45100;font-weight:750}.source-architecture,.source-proof{display:grid;grid-template-columns:1fr 1fr;gap:65px;align-items:center}.source-stack{border-top:3px solid var(--orange)}.source-stack div{padding:17px 0;border-bottom:1px solid var(--line)}.source-stack strong,.source-stack span{display:block}.source-stack span{color:var(--muted)}.source-teaser{background:#eaf1f5}.spe-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.spe-grid article{background:#fff;padding:26px;border:1px solid var(--line);border-top:4px solid var(--steel)}.spe-grid article>span{display:inline-grid;place-items:center;width:48px;height:48px;background:var(--navy);color:#fff;font:700 1.35rem 'Exo 2',sans-serif}.spe-grid h3{margin:20px 0 10px}.spe-grid p{color:var(--muted)}.spe-workflow{display:grid;grid-template-columns:repeat(3,1fr);gap:0;margin-top:29px;border:1px solid var(--line)}.spe-workflow>div{padding:23px;border-right:1px solid var(--line)}.spe-workflow>div:last-child{border:0}.spe-workflow strong,.spe-workflow span{display:block}.spe-workflow span{color:var(--muted);margin-top:8px}.spe-note{font-size:.92rem;color:var(--muted);margin:18px 0 0}body[data-theme="dark"] .source-adapt-grid article,body[data-theme="dark"] .spe-grid article{background:#173a52;border-color:#3e6076}body[data-theme="dark"] .source-teaser{background:#102f47}body[data-theme="dark"] .source-adapt-grid span,body[data-theme="dark"] .source-adapt-grid a{color:#ffb76f}@media(max-width:900px){.source-architecture,.source-proof{grid-template-columns:1fr;gap:35px}.spe-workflow{grid-template-columns:1fr}.spe-workflow>div{border-right:0;border-bottom:1px solid var(--line)}.spe-workflow>div:last-child{border-bottom:0}}@media(max-width:700px){.source-hero{padding:52px 0 62px}.source-adapt-grid,.spe-grid{grid-template-columns:1fr}}
'''
with (P/'styles.css').open('a') as out:out.write(css)
